retry(): void {
    if (this.stopped || this.snapshot.status !== 'failed') return
    this.queued = []
    this.commit({ status: 'loading', failure: null, worktree: null, sessions: [] })
    void this.load()
  }

private async load(): Promise<void> {
    if (this.loading) {
      this.reloadAfter = true
      return
    }
    this.loading = true
    try {
      do {
        this.reloadAfter = false
        await this.loadOnce()
      } while (this.reloadAfter && !this.stopped)
    } finally {
      this.loading = false
    }
  }

private async loadOnce(): Promise<void> {
    let worktree: Worktree
    let sessions: Session[]
    try {
      worktree = (await this.context.call('quirky.worktree/resolve', { selector: this.selector })) as Worktree
      sessions = (await this.context.call('quirky.session/list', { worktree: worktree.id })) as Session[]
    } catch (error) {
      if (this.stopped) return
      const gone = (error as { code?: unknown } | null)?.code === RpcErrorCode.NotFound
      this.queued = []
      if (gone) this.commit({ status: 'missing', failure: null, worktree: null, sessions: [] })
      else if (this.snapshot.status === 'ready') this.context.toast('Could not load sessions', messageOf(error))
      else this.commit({ status: 'failed', failure: messageOf(error), worktree: null, sessions: [] })
      return
    }
    if (this.stopped) return
    const byId = new Map(sessions.map((session) => [session.id, session]))
    for (const event of this.queued.splice(0)) this.applyToMap(byId, event, worktree.id)
    const loadedSessions = [...byId.values()]
    pruneShowAllEvents(worktree.id, loadedSessions)
    this.commit({
      status: 'ready',
      failure: null,
      worktree: { id: worktree.id, name: worktree.name, path: worktree.path },
      sessions: loadedSessions
    })
  }

